using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer;

/// <summary>
/// MCP tools that wrap a weather REST API.
/// Constructor-injected HttpClient is provided by DI (IHttpClientFactory).
/// </summary>
[McpServerToolType]
public sealed class WeatherTools(HttpClient httpClient)
{
    private const string BaseUrl = "https://api.open-meteo.com/v1";

    [McpServerTool, Description("Get current weather for a location by latitude and longitude.")]
    public async Task<string> GetCurrentWeather(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        CancellationToken cancellationToken = default)
    {
        var url = $"{BaseUrl}/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m,relative_humidity_2m";

        var response = await httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellationToken), cancellationToken: cancellationToken);

        var current = doc.RootElement.GetProperty("current");
        var units = doc.RootElement.GetProperty("current_units");

        return $"Temperature: {current.GetProperty("temperature_2m")}{units.GetProperty("temperature_2m")}, "
             + $"Wind: {current.GetProperty("wind_speed_10m")}{units.GetProperty("wind_speed_10m")}, "
             + $"Humidity: {current.GetProperty("relative_humidity_2m")}{units.GetProperty("relative_humidity_2m")}";
    }

    [McpServerTool, Description("Get a multi-day weather forecast for a location.")]
    public async Task<string> GetForecast(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        [Description("Number of forecast days (1-16)")] int days = 3,
        CancellationToken cancellationToken = default)
    {
        days = Math.Clamp(days, 1, 16);

        var url = $"{BaseUrl}/forecast?latitude={latitude}&longitude={longitude}"
                + $"&daily=temperature_2m_max,temperature_2m_min&forecast_days={days}";

        var response = await httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellationToken), cancellationToken: cancellationToken);

        var daily = doc.RootElement.GetProperty("daily");
        var dates = daily.GetProperty("time");
        var highs = daily.GetProperty("temperature_2m_max");
        var lows = daily.GetProperty("temperature_2m_min");

        var lines = new List<string>();
        for (var i = 0; i < dates.GetArrayLength(); i++)
        {
            lines.Add($"{dates[i].GetString()}: High {highs[i]}°C, Low {lows[i]}°C");
        }

        return string.Join("\n", lines);
    }
}

