using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    .AddMcpServer(options =>
    {
        options.ServerInfo = new() { Name = "weather-server", Version = "1.0.0" };
    })
    .WithStdioServerTransport()
    .WithTools<McpServer.WeatherTools>();

// IHttpClientFactory creates short-lived handlers to avoid socket exhaustion.
builder.Services.AddHttpClient<McpServer.WeatherTools>();

await builder.Build().RunAsync();

