17.     public async Task<string> GetCurrentWeather(
18.         [Description("Latitude of the location")] double latitude,
19.         [Description("Longitude of the location")] double longitude,
20.         CancellationToken cancellationToken = default)
21.     {
22.         var url = $"{BaseUrl}/forecast?latitude={latitude}&longitude={longitude}"
23.                 + "&current=temperature_2m,wind_speed_10m,relative_humidity_2m";
24. 
25.         var response = await httpClient.GetAsync(url, cancellationToken);
26.         response.EnsureSuccessStatusCode();
27. 
28.         using var doc = await JsonDocument.ParseAsync(
29.             await response.Content.ReadAsStreamAsync(cancellationToken), cancellationToken: cancellationToken);
30. 
31.         var current = doc.RootElement.GetProperty("current");
32.         var units = doc.RootElement.GetProperty("current_units");
33. 
34.         return $"Temperature: {current.GetProperty("temperature_2m")}{units.GetProperty("temperature_2m")}, "
35.              + $"Wind: {current.GetProperty("wind_speed_10m")}{units.GetProperty("wind_speed_10m")}, "
36.              + $"Humidity: {current.GetProperty("relative_humidity_2m")}{units.GetProperty("relative_humidity_2m")}";
37.     }
38. 
