40.     public async Task<string> GetForecast(
41.         [Description("Latitude of the location")] double latitude,
42.         [Description("Longitude of the location")] double longitude,
43.         [Description("Number of forecast days (1-16)")] int days = 3,
44.         CancellationToken cancellationToken = default)
45.     {
46.         days = Math.Clamp(days, 1, 16);
47. 
48.         var url = $"{BaseUrl}/forecast?latitude={latitude}&longitude={longitude}"
49.                 + $"&daily=temperature_2m_max,temperature_2m_min&forecast_days={days}";
50. 
51.         var response = await httpClient.GetAsync(url, cancellationToken);
52.         response.EnsureSuccessStatusCode();
53. 
54.         using var doc = await JsonDocument.ParseAsync(
55.             await response.Content.ReadAsStreamAsync(cancellationToken), cancellationToken: cancellationToken);
56. 
